/* Loc Style Finder catalogue. Shared by the page (as a plain script) and tools/gen_images.py (via node). */
/* ---------------- attribute schema ---------------- */
const ATTRS = [
  {key:'thickness', label:'Loc thickness', type:'num', min:1, max:5, w:1.6,
   levels:['','Micro (2–4 mm)','Small (4–7 mm)','Medium (7–13 mm)','Thick (13–20 mm)','Jumbo / wick (20 mm+)'],
   why:'Diameter of each loc. Sisterlocks at the thin end, wicks at the thick end.'},
  {key:'length', label:'Length', type:'num', min:1, max:5, w:1.5,
   levels:['','Starter (under 4 in)','Short (ear)','Medium (chin to shoulder)','Long (chest)','Extra long (waist+)'],
   why:'How far the locs fall when hanging.'},
  {key:'sides', label:'Sides and back', type:'num', min:0, max:4, w:1.3,
   levels:['Full head','Taper','Fade','Undercut / shaved sides','Mohawk strip'],
   why:'How much of the sides and back is cut away. 0 is a full head of locs.'},
  {key:'neatness', label:'Root discipline', type:'num', min:1, max:4, w:1.0,
   levels:['','Freeform','Semi-freeform','Manicured','Precision grid'],
   why:'From hair left to lock on its own, to an interlocked grid with retightened parts.'},
  {key:'roots', label:'Root styling', type:'num', min:0, max:2, w:0.8,
   levels:['Loose roots','Twisted roots','Braided roots'],
   why:'Whether the locs are twisted or braided together at the scalp.'},
  {key:'arrange', label:'How it is worn', type:'num', min:0, max:3, w:1.0,
   levels:['Hanging free','Half up','Tied up (bun or tail)','Standing up'],
   why:'Resting position of the locs.'},
  {key:'color', label:'Colour', type:'num', min:0, max:3, w:0.7,
   levels:['Natural','Dyed tips','Ombre / highlights','Full colour'],
   why:'How much of the loc is coloured.'},
  {key:'maint', label:'Upkeep', type:'num', min:1, max:5, w:0.9,
   levels:['','Minimal','Low','Moderate','High','Very high'],
   why:'Retwist, restyle and salon frequency combined.'},
  {key:'count', label:'Number of locs', type:'log', min:Math.log(4), max:Math.log(450), w:0.6,
   fmt:v=>'about '+v, why:'Approximate locs on a full head. Scored on a log scale.'},
  {key:'surface', label:'Surface texture', type:'cat', w:0.6,
   why:'What the body of the loc looks like up close.'},
  {key:'formality', label:'Dress code fit', type:'num', min:1, max:5, w:0.5,
   levels:['','Streetwear','Casual','Smart casual','Office-friendly','Conservative'],
   why:'A rough read of how the style lands in formal settings.'},
  {key:'months', label:'Time to achieve', type:'log', min:0, max:Math.log1p(60), w:0.5,
   fmt:v=>v===0?'same day':v+' months', why:'Months of growth or maturity needed before the look reads as intended. Scored on a log scale.'},
  {key:'permanent', label:'Permanence', type:'cat', w:0.8, fmt:v=>v?'Permanent':'Temporary',
   why:'Real locs versus a removable installed style.'},
  {key:'start', label:'How it is started', type:'cat', w:0.3,
   why:'The method that forms the locs.'},
  {key:'parting', label:'Parting pattern', type:'cat', w:0.4,
   why:'Shape of the sections on the scalp.'},
  {key:'crown', label:'Crown, seen from above', type:'cat', w:0.6,
   why:'What the top of the head shows: a grid of loc bases, a knot, rows, or an unparted mat.'},
  {key:'nape', label:'Nape, seen from behind', type:'cat', w:0.6,
   why:'What the back of the neck shows: locs falling down the back, a tail, a bare faded nape, or a hard shaved edge.'},
  {key:'method', label:'Construction', type:'cat', w:0.7,
   why:'How the body of the loc is actually built: comb coil, two-strand twist, three-strand braid, palm roll, interlock, crochet, freeform matting, combined locs, a style laid over existing locs, or a wrapped extension.'},
  {key:'section', label:'Section size', type:'log', min:0, max:Math.log1p(3), w:0.6, fmt:v=>v?`about ${v} in squares`:'no parting',
   why:'Side of the parting square each loc grows from, in inches. Scored on a log scale; freeform has no parting.'},
  {key:'ends', label:'Ends', type:'cat', w:0.4,
   why:'What the tips look like: tapered, blunt, curly and open, coiled, sealed, or frayed.'},
  {key:'stage', label:'Maturity needed', type:'num', min:0, max:4, w:0.6,
   levels:['Same-day install','Starter (0–3 months)','Budding (3–9 months)','Mature (1–2 years)','Rooted (2+ years)'],
   why:'How far along the locking journey the hair must be for the look to read as intended.'},
];
const AT = Object.fromEntries(ATTRS.map(a=>[a.key,a]));

